using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.Models;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Settings.Materials;public class EditModel(ApplicationDbContext db,IPermissionService permissions):PageModel{[BindProperty]public Material Item{get;set;}=null!;public Microsoft.AspNetCore.Mvc.Rendering.SelectList Units{get;private set;}=null!;public async Task<IActionResult> OnGetAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.Materials,PermissionAction.Update))return Forbid();var item=await db.Materials.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id);if(item is null)return NotFound();Item=item;await Load();return Page();}public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.Materials,PermissionAction.Update))return Forbid();if(!await db.Units.AnyAsync(x=>x.Id==Item.UnitOfMeasureId))ModelState.AddModelError("Item.UnitOfMeasureId","اختر وحدة صحيحة");if(!ModelState.IsValid){await Load();return Page();}var x=await db.Materials.SingleOrDefaultAsync(x=>x.Id==Item.Id);if(x is null)return NotFound();x.Name=Item.Name;x.UnitOfMeasureId=Item.UnitOfMeasureId;x.Notes=Item.Notes;await db.SaveChangesAsync();TempData["Message"]="تم تعديل الخامة";return RedirectToPage("Index");}private async Task Load()=>Units=new Microsoft.AspNetCore.Mvc.Rendering.SelectList(await db.Units.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");}
